CREATE OR REPLACE FUNCTION "public"."approve_join_request"("p_request_id" "uuid", "p_reviewer_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_organization_id UUID;
  v_user_id UUID;
  v_status TEXT;
BEGIN
  -- Get request details
  SELECT organization_id, user_id, status
  INTO v_organization_id, v_user_id, v_status
  FROM organization_join_requests
  WHERE id = p_request_id;

  -- Check if request exists and is pending
  IF NOT FOUND OR v_status != 'pending' THEN
    RETURN FALSE;
  END IF;

  -- Check if reviewer is admin/owner of the organization
  IF NOT EXISTS (
    SELECT 1 FROM organization_members
    WHERE organization_id = v_organization_id
    AND user_id = p_reviewer_id
    AND role IN ('Owner', 'Admin')
  ) THEN
    RETURN FALSE;
  END IF;

  -- Update request status
  UPDATE organization_join_requests
  SET 
    status = 'approved',
    reviewed_at = NOW(),
    reviewed_by = p_reviewer_id,
    updated_at = NOW()
  WHERE id = p_request_id;

  -- Add user to organization as Member
  INSERT INTO organization_members (organization_id, user_id, role)
  VALUES (v_organization_id, v_user_id, 'Member')
  ON CONFLICT (organization_id, user_id) DO NOTHING;

  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."approve_join_request"("p_request_id" "uuid", "p_reviewer_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."approve_join_request"("p_request_id" "uuid", "p_reviewer_id" "uuid") IS 'Approves a join request and adds the user to the organization';



CREATE OR REPLACE FUNCTION "public"."can_create_event_in_org"("p_organization_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM organization_members
        WHERE organization_id = p_organization_id
            AND user_id = p_user_id
            AND role IN ('Owner', 'Admin', 'Attendance Taker')
    );
$$;


ALTER FUNCTION "public"."can_create_event_in_org"("p_organization_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_manage_event"("p_event_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
    SELECT EXISTS (
        -- User is the creator
        SELECT 1
        FROM events e
        WHERE e.id = p_event_id
            AND e.created_by = p_user_id
    ) OR EXISTS (
        -- User is Owner or Admin of the organization
        SELECT 1
        FROM events e
        JOIN organization_members om ON om.organization_id = e.organization_id
        WHERE e.id = p_event_id
            AND om.user_id = p_user_id
            AND om.role IN ('Owner', 'Admin')
    );
$$;


ALTER FUNCTION "public"."can_manage_event"("p_event_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_take_attendance"("p_event_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_org_id UUID;
    v_can_take BOOLEAN;
BEGIN
    -- Get organization ID from event
    SELECT organization_id INTO v_org_id
    FROM events
    WHERE id = p_event_id;
    
    IF v_org_id IS NULL THEN
        RETURN FALSE;
    END IF;
    
    -- Check if user has Attendance Taker permission or higher
    v_can_take := user_has_permission(p_user_id, v_org_id, 'Attendance Taker');
    
    RETURN v_can_take;
END;
$$;


ALTER FUNCTION "public"."can_take_attendance"("p_event_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_take_attendance"("p_event_id" "uuid", "p_user_id" "uuid") IS 'Checks if user has permission to take attendance for an event';



CREATE OR REPLACE FUNCTION "public"."can_user_write_tag"("p_user_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_last_write_date TIMESTAMP WITH TIME ZONE;
    v_cooldown_days INTEGER := 14; -- DEVELOPER NOTE: Modify this value to change cooldown period
    v_next_available_date TIMESTAMP WITH TIME ZONE;
    v_can_write BOOLEAN;
BEGIN
    -- Get the most recent tag write date for this user
    SELECT written_at INTO v_last_write_date
    FROM user_tag_writes
    WHERE user_id = p_user_id
    ORDER BY written_at DESC
    LIMIT 1;
    
    -- If no previous writes, user can write immediately
    IF v_last_write_date IS NULL THEN
        RETURN json_build_object(
            'can_write', TRUE,
            'next_available_date', NULL,
            'last_write_date', NULL,
            'cooldown_days', v_cooldown_days
        );
    END IF;
    
    -- Calculate next available write date
    v_next_available_date := v_last_write_date + (v_cooldown_days || ' days')::INTERVAL;
    
    -- Check if cooldown period has passed
    v_can_write := NOW() >= v_next_available_date;
    
    RETURN json_build_object(
        'can_write', v_can_write,
        'next_available_date', v_next_available_date,
        'last_write_date', v_last_write_date,
        'cooldown_days', v_cooldown_days
    );
END;
$$;


ALTER FUNCTION "public"."can_user_write_tag"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_user_write_tag"("p_user_id" "uuid") IS 'Checks if user can write a new tag based on 14-day cooldown period';



CREATE OR REPLACE FUNCTION "public"."check_single_owner"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.role = 'Owner' THEN
    -- Check if there's already an owner for this organization (excluding current record)
    IF EXISTS (
      SELECT 1 FROM organization_members
      WHERE organization_id = NEW.organization_id
      AND role = 'Owner'
      AND id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::UUID)
    ) THEN
      RAISE EXCEPTION 'Organization can only have one owner. Use transfer ownership instead.';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_single_owner"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_expired_event_files"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_deleted_count INTEGER := 0;
    v_file_record RECORD;
    v_storage_paths TEXT[] := ARRAY[]::TEXT[];
BEGIN
    -- Find and delete expired event files
    -- Files are eligible for deletion 3 days after the event date
    FOR v_file_record IN
        SELECT ef.id, ef.storage_path, ef.file_name, e.event_name, e.date
        FROM event_files ef
        INNER JOIN events e ON e.id = ef.event_id
        WHERE e.date + INTERVAL '3 days' < NOW()
    LOOP
        -- Collect storage path for reference
        v_storage_paths := array_append(v_storage_paths, v_file_record.storage_path);
        
        -- Delete from database (triggers cascade)
        DELETE FROM event_files WHERE id = v_file_record.id;
        
        v_deleted_count := v_deleted_count + 1;
    END LOOP;
    
    -- Also cleanup orphaned featured images from expired events
    UPDATE events
    SET featured_image_url = NULL,
        featured_image_storage_path = NULL
    WHERE date + INTERVAL '3 days' < NOW()
      AND featured_image_url IS NOT NULL;
    
    RETURN json_build_object(
        'success', TRUE,
        'files_deleted', v_deleted_count,
        'storage_paths', v_storage_paths,
        'message', format('Deleted %s expired event files', v_deleted_count)
    );
END;
$$;


ALTER FUNCTION "public"."cleanup_expired_event_files"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_expired_event_files"() IS 'Removes files from events that ended more than 3 days ago. Call via admin API endpoint.';



CREATE OR REPLACE FUNCTION "public"."cleanup_expired_pending_tags"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_deleted_count INTEGER;
BEGIN
    DELETE FROM user_tag_pending
    WHERE expires_at < NOW() 
      AND confirmed = FALSE;
    
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    
    RETURN v_deleted_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_expired_pending_tags"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_expired_pending_tags"() IS 'Removes expired unconfirmed pending tags';



CREATE OR REPLACE FUNCTION "public"."confirm_tag_update"("p_user_id" "uuid", "p_tag_id" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_can_write_result JSON;
    v_can_write BOOLEAN;
    v_write_record_id UUID;
BEGIN
    -- Check if user can write a new tag
    v_can_write_result := can_user_write_tag(p_user_id);
    v_can_write := (v_can_write_result->>'can_write')::BOOLEAN;
    
    IF NOT v_can_write THEN
        RAISE EXCEPTION 'Cannot write tag. Cooldown period not elapsed. Next available: %', 
            v_can_write_result->>'next_available_date';
    END IF;
    
    -- Update user's tag_id
    UPDATE users 
    SET tag_id = p_tag_id,
        updated_at = NOW()
    WHERE id = p_user_id;
    
    -- Record the tag write in history
    INSERT INTO user_tag_writes (user_id, tag_id, written_at)
    VALUES (p_user_id, p_tag_id, NOW())
    RETURNING id INTO v_write_record_id;
    
    RETURN json_build_object(
        'success', TRUE,
        'tag_id', p_tag_id,
        'write_record_id', v_write_record_id,
        'written_at', NOW()
    );
END;
$$;


ALTER FUNCTION "public"."confirm_tag_update"("p_user_id" "uuid", "p_tag_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."confirm_tag_update"("p_user_id" "uuid", "p_tag_id" "text") IS 'Updates tag ID and records write history if cooldown period has elapsed';



CREATE OR REPLACE FUNCTION "public"."confirm_tag_write"("p_user_id" "uuid", "p_pending_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_tag_id TEXT;
    v_write_record_id UUID;
    v_expired BOOLEAN;
    v_already_confirmed BOOLEAN;
BEGIN
    -- Fetch the pending record
    SELECT 
        tag_id,
        expires_at < NOW() AS is_expired,
        confirmed
    INTO v_tag_id, v_expired, v_already_confirmed
    FROM user_tag_pending
    WHERE id = p_pending_id 
      AND user_id = p_user_id;
    
    -- Check if record exists
    IF v_tag_id IS NULL THEN
        RAISE EXCEPTION 'Pending tag record not found';
    END IF;
    
    -- Check if expired
    IF v_expired THEN
        RAISE EXCEPTION 'Pending tag has expired. Please generate a new one.';
    END IF;
    
    -- Check if already confirmed
    IF v_already_confirmed THEN
        RAISE EXCEPTION 'Tag already confirmed';
    END IF;
    
    -- Update user's tag_id
    UPDATE users 
    SET tag_id = v_tag_id,
        updated_at = NOW()
    WHERE id = p_user_id;
    
    -- Record the tag write in history
    INSERT INTO user_tag_writes (user_id, tag_id, written_at)
    VALUES (p_user_id, v_tag_id, NOW())
    RETURNING id INTO v_write_record_id;
    
    -- Mark pending record as confirmed
    UPDATE user_tag_pending
    SET confirmed = TRUE,
        confirmed_at = NOW()
    WHERE id = p_pending_id;
    
    RETURN json_build_object(
        'success', TRUE,
        'tag_id', v_tag_id,
        'write_record_id', v_write_record_id,
        'written_at', NOW()
    );
END;
$$;


ALTER FUNCTION "public"."confirm_tag_write"("p_user_id" "uuid", "p_pending_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."confirm_tag_write"("p_user_id" "uuid", "p_pending_id" "uuid") IS 'Confirms a pending tag write after successful NFC write';



CREATE OR REPLACE FUNCTION "public"."generate_and_assign_tag"("p_user_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_new_tag_id UUID;
    v_can_write_result JSON;
    v_can_write BOOLEAN;
    v_write_record_id UUID;
BEGIN
    -- Check if user can write a new tag
    v_can_write_result := can_user_write_tag(p_user_id);
    v_can_write := (v_can_write_result->>'can_write')::BOOLEAN;
    
    IF NOT v_can_write THEN
        RAISE EXCEPTION 'Cannot write tag. Cooldown period not elapsed. Next available: %', 
            v_can_write_result->>'next_available_date';
    END IF;
    
    -- Generate new UUID for tag
    v_new_tag_id := gen_random_uuid();
    
    -- Update user's tag_id
    UPDATE users 
    SET tag_id = v_new_tag_id::TEXT,
        updated_at = NOW()
    WHERE id = p_user_id;
    
    -- Record the tag write in history
    INSERT INTO user_tag_writes (user_id, tag_id, written_at)
    VALUES (p_user_id, v_new_tag_id::TEXT, NOW())
    RETURNING id INTO v_write_record_id;
    
    RETURN json_build_object(
        'success', TRUE,
        'tag_id', v_new_tag_id,
        'write_record_id', v_write_record_id,
        'written_at', NOW()
    );
END;
$$;


ALTER FUNCTION "public"."generate_and_assign_tag"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."generate_and_assign_tag"("p_user_id" "uuid") IS 'Generates new tag ID for user if cooldown period has elapsed';



CREATE OR REPLACE FUNCTION "public"."get_active_calendar_syncs_for_org"("org_id" "uuid") RETURNS TABLE("sync_id" "uuid", "membership_id" "uuid", "user_id" "uuid", "google_refresh_token_encrypted" "text", "google_access_token_encrypted" "text", "token_expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        mcs.id AS sync_id,
        mcs.membership_id,
        om.user_id,
        mcs.google_refresh_token_encrypted,
        mcs.google_access_token_encrypted,
        mcs.token_expires_at
    FROM member_calendar_sync mcs
    JOIN organization_members om ON om.id = mcs.membership_id
    WHERE om.organization_id = org_id
    AND mcs.sync_status = 'active';
END;
$$;


