CREATE OR REPLACE FUNCTION "public"."get_user_role_in_organization"("p_user_id" "uuid", "p_organization_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_role TEXT;
BEGIN
  SELECT role INTO v_role
  FROM organization_members
  WHERE user_id = p_user_id
  AND organization_id = p_organization_id;
  
  RETURN v_role;
END;
$$;


