CREATE OR REPLACE FUNCTION "public"."is_user_attended"("p_event_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_attended BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM event_attendance
        WHERE event_id = p_event_id AND user_id = p_user_id
    ) INTO v_attended;
    
    RETURN v_attended;
END;
$$;


ALTER FUNCTION "public"."is_user_attended"("p_event_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."is_user_attended"("p_event_id" "uuid", "p_user_id" "uuid") IS 'Checks if a user has attended a specific event';



CREATE OR REPLACE FUNCTION "public"."mark_attendance"("p_event_id" "uuid", "p_user_id" "uuid", "p_marked_by" "uuid", "p_scan_method" "text", "p_location_lat" numeric DEFAULT NULL::numeric, "p_location_lng" numeric DEFAULT NULL::numeric, "p_notes" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_attendance_id UUID;
    v_existing_attendance UUID;
    v_event_org_id UUID;
    v_user_is_member BOOLEAN;
    v_marker_can_take_attendance BOOLEAN;
BEGIN
    -- Check if attendance already exists
    SELECT id INTO v_existing_attendance
    FROM event_attendance
    WHERE event_id = p_event_id AND user_id = p_user_id;
    
    IF v_existing_attendance IS NOT NULL THEN
        RAISE EXCEPTION 'Attendance already marked for this user at this event';
    END IF;
    
    -- Get event's organization
    SELECT organization_id INTO v_event_org_id
    FROM events
    WHERE id = p_event_id;
    
    IF v_event_org_id IS NULL THEN
        RAISE EXCEPTION 'Event not found';
    END IF;
    
    -- Check if user is a member of the organization (but don't require it)
    v_user_is_member := is_org_member(v_event_org_id, p_user_id);
    
    -- Verify marker has permission to take attendance
    v_marker_can_take_attendance := user_has_permission(p_marked_by, v_event_org_id, 'Attendance Taker');
    
    IF NOT v_marker_can_take_attendance THEN
        RAISE EXCEPTION 'Marker does not have permission to take attendance';
    END IF;
    
    -- Insert attendance record (now includes is_member flag)
    INSERT INTO event_attendance (
        event_id, user_id, marked_by, scan_method,
        location_lat, location_lng, notes, marked_at, is_member
    )
    VALUES (
        p_event_id, p_user_id, p_marked_by, p_scan_method,
        p_location_lat, p_location_lng, p_notes, NOW(), v_user_is_member
    )
    RETURNING id INTO v_attendance_id;
    
    RETURN json_build_object(
        'success', TRUE,
        'attendance_id', v_attendance_id,
        'marked_at', NOW(),
        'is_member', v_user_is_member
    );
END;
$$;


ALTER FUNCTION "public"."mark_attendance"("p_event_id" "uuid", "p_user_id" "uuid", "p_marked_by" "uuid", "p_scan_method" "text", "p_location_lat" numeric, "p_location_lng" numeric, "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mark_attendance"("p_event_id" "uuid", "p_user_id" "uuid", "p_marked_by" "uuid", "p_scan_method" "text", "p_location_lat" numeric, "p_location_lng" numeric, "p_notes" "text") IS 'Marks user attendance at an event. Supports both members and non-members (guests). Auto-detects membership status.';



