CREATE OR REPLACE FUNCTION "public"."user_can_reset_password"("user_email" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  user_record RECORD;
BEGIN
  SELECT auth_provider, has_password INTO user_record
  FROM users
  WHERE email = user_email;
  
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  
  -- User can reset password if they have one set OR if they're an email user
  RETURN user_record.has_password OR user_record.auth_provider = 'email';
END;
$$;


ALTER FUNCTION "public"."user_can_reset_password"("user_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_has_permission"("p_user_id" "uuid", "p_organization_id" "uuid", "p_required_role" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_user_role TEXT;
  v_role_level INT;
  v_required_level INT;
BEGIN
  -- Get user's role
  SELECT role INTO v_user_role
  FROM organization_members
  WHERE user_id = p_user_id
  AND organization_id = p_organization_id;

  -- If no membership found, return false
  IF v_user_role IS NULL THEN
    RETURN FALSE;
  END IF;

  -- Define role hierarchy
  v_role_level := CASE v_user_role
    WHEN 'Owner' THEN 4
    WHEN 'Admin' THEN 3
    WHEN 'Attendance Taker' THEN 2
    WHEN 'Member' THEN 1
    ELSE 0
  END;

  v_required_level := CASE p_required_role
    WHEN 'Owner' THEN 4
    WHEN 'Admin' THEN 3
    WHEN 'Attendance Taker' THEN 2
    WHEN 'Member' THEN 1
    ELSE 0
  END;

  RETURN v_role_level >= v_required_level;
END;
$$;


ALTER FUNCTION "public"."user_has_permission"("p_user_id" "uuid", "p_organization_id" "uuid", "p_required_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_has_role"("p_user_id" "uuid", "p_organization_id" "uuid", "p_role" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM organization_members
    WHERE user_id = p_user_id
    AND organization_id = p_organization_id
    AND role = p_role
  );
END;
$$;


ALTER FUNCTION "public"."user_has_role"("p_user_id" "uuid", "p_organization_id" "uuid", "p_role" "text") OWNER TO "postgres";

