    "marked_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "marked_by" "uuid" NOT NULL,
    "scan_method" "text" NOT NULL,
    "location_lat" numeric(10,8),
    "location_lng" numeric(11,8),
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_member" boolean DEFAULT true NOT NULL,
    CONSTRAINT "notes_length" CHECK ((("notes" IS NULL) OR ("length"("notes") <= 1000))),
    CONSTRAINT "valid_latitude" CHECK ((("location_lat" IS NULL) OR (("location_lat" >= ('-90'::integer)::numeric) AND ("location_lat" <= (90)::numeric)))),
    CONSTRAINT "valid_longitude" CHECK ((("location_lng" IS NULL) OR (("location_lng" >= ('-180'::integer)::numeric) AND ("location_lng" <= (180)::numeric)))),
    CONSTRAINT "valid_scan_method" CHECK (("scan_method" = ANY (ARRAY['NFC'::"text", 'QR'::"text", 'Manual'::"text"])))
);

