CREATE OR REPLACE VIEW "public"."attendance_with_details" AS
 SELECT "ea"."id",
    "ea"."event_id",
    "ea"."user_id",
    "ea"."marked_at",
    "ea"."marked_by",
    "ea"."scan_method",
    "ea"."location_lat",
    "ea"."location_lng",
    "ea"."notes",
    "ea"."is_member",
    "ea"."created_at",
    "ea"."updated_at",
    "u"."name" AS "user_name",
    "u"."email" AS "user_email",
    "u"."user_type",
    "e"."event_name",
    "e"."date" AS "event_date",
    "e"."location" AS "event_location",
    "e"."organization_id",
    "o"."name" AS "organization_name",
    "mb"."name" AS "marked_by_name",
    "mb"."email" AS "marked_by_email"
   FROM (((("public"."event_attendance" "ea"
     JOIN "public"."users" "u" ON (("ea"."user_id" = "u"."id")))
     JOIN "public"."events" "e" ON (("ea"."event_id" = "e"."id")))
     JOIN "public"."organizations" "o" ON (("e"."organization_id" = "o"."id")))
     JOIN "public"."users" "mb" ON (("ea"."marked_by" = "mb"."id")));


ALTER VIEW "public"."attendance_with_details" OWNER TO "postgres";


COMMENT ON VIEW "public"."attendance_with_details" IS 'Complete attendance records with user, event, organization details and member status';



