CREATE OR REPLACE VIEW "public"."event_attendance_summary" AS
 SELECT "e"."id" AS "event_id",
    "e"."event_name",
    "e"."date" AS "event_date",
    "e"."organization_id",
    "o"."name" AS "organization_name",
    COALESCE("att"."total_attended", (0)::bigint) AS "total_attended",
    COALESCE("mem"."total_members", (0)::bigint) AS "total_members",
        CASE
            WHEN (COALESCE("mem"."total_members", (0)::bigint) = 0) THEN (0)::numeric
            ELSE "round"((((COALESCE("att"."total_attended", (0)::bigint))::numeric / ("mem"."total_members")::numeric) * (100)::numeric), 1)
        END AS "attendance_percentage",
    COALESCE("att"."nfc_scans", (0)::bigint) AS "nfc_scans",
    COALESCE("att"."qr_scans", (0)::bigint) AS "qr_scans",
    COALESCE("att"."manual_entries", (0)::bigint) AS "manual_entries",
    COALESCE("att"."member_count", (0)::bigint) AS "member_count",
    COALESCE("att"."non_member_count", (0)::bigint) AS "non_member_count",
    "att"."last_attendance_marked"
   FROM ((("public"."events" "e"
     JOIN "public"."organizations" "o" ON (("e"."organization_id" = "o"."id")))
     LEFT JOIN ( SELECT "event_attendance"."event_id",
            "count"(*) AS "total_attended",
            "count"(*) FILTER (WHERE ("event_attendance"."scan_method" = 'NFC'::"text")) AS "nfc_scans",
            "count"(*) FILTER (WHERE ("event_attendance"."scan_method" = 'QR'::"text")) AS "qr_scans",
            "count"(*) FILTER (WHERE ("event_attendance"."scan_method" = 'Manual'::"text")) AS "manual_entries",
            "count"(*) FILTER (WHERE ("event_attendance"."is_member" = true)) AS "member_count",
            "count"(*) FILTER (WHERE ("event_attendance"."is_member" = false)) AS "non_member_count",
            "max"("event_attendance"."marked_at") AS "last_attendance_marked"
           FROM "public"."event_attendance"
          GROUP BY "event_attendance"."event_id") "att" ON (("e"."id" = "att"."event_id")))
     LEFT JOIN ( SELECT "organization_members"."organization_id",
            "count"(*) AS "total_members"
           FROM "public"."organization_members"
          GROUP BY "organization_members"."organization_id") "mem" ON (("e"."organization_id" = "mem"."organization_id")));


ALTER VIEW "public"."event_attendance_summary" OWNER TO "postgres";


COMMENT ON VIEW "public"."event_attendance_summary" IS 'Summary statistics for event attendance including member and non-member (guest) counts';



