CREATE OR REPLACE VIEW "public"."events_with_details" WITH ("security_invoker"='on') AS
 SELECT "e"."id",
    "e"."event_name",
    "e"."date",
    "e"."organization_id",
    "e"."description",
    "e"."location",
    "e"."created_by",
    "e"."created_at",
    "e"."updated_at",
    "o"."name" AS "organization_name",
    "o"."tag" AS "organization_tag",
    "o"."description" AS "organization_description",
    "u"."name" AS "creator_name",
    "u"."email" AS "creator_email",
    "u"."user_type" AS "creator_user_type"
   FROM (("public"."events" "e"
     JOIN "public"."organizations" "o" ON (("o"."id" = "e"."organization_id")))
     JOIN "public"."users" "u" ON (("u"."id" = "e"."created_by")));


ALTER VIEW "public"."events_with_details" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."member_calendar_sync" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "membership_id" "uuid" NOT NULL,
    "google_refresh_token_encrypted" "text",
    "google_access_token_encrypted" "text",
    "token_expires_at" timestamp with time zone,
    "last_sync_at" timestamp with time zone,
    "sync_status" "text" DEFAULT 'disconnected'::"text" NOT NULL,
    "last_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "member_calendar_sync_sync_status_check" CHECK (("sync_status" = ANY (ARRAY['active'::"text", 'failed'::"text", 'disconnected'::"text"])))
);


ALTER TABLE "public"."member_calendar_sync" OWNER TO "postgres";


COMMENT ON TABLE "public"."member_calendar_sync" IS 'Stores encrypted Google OAuth tokens for calendar sync per organization membership';



COMMENT ON COLUMN "public"."member_calendar_sync"."google_refresh_token_encrypted" IS 'AES-256-GCM encrypted Google OAuth refresh token';



COMMENT ON COLUMN "public"."member_calendar_sync"."google_access_token_encrypted" IS 'AES-256-GCM encrypted Google OAuth access token';



COMMENT ON COLUMN "public"."member_calendar_sync"."sync_status" IS 'Status of calendar sync: active (working), failed (needs reconnection), disconnected (user disabled)';



