CREATE OR REPLACE VIEW "public"."past_events" AS
 SELECT "e"."id",
    "e"."event_name",
    "e"."date",
    "e"."organization_id",
    "e"."description",
    "e"."location",
    "e"."created_by",
    "e"."created_at",
    "e"."updated_at",
    "e"."event_start",
    "e"."event_end",
    "o"."name" AS "organization_name",
    "o"."tag" AS "organization_tag"
   FROM ("public"."events" "e"
     JOIN "public"."organizations" "o" ON (("o"."id" = "e"."organization_id")))
  WHERE ((("e"."event_end" IS NOT NULL) AND ("e"."event_end" < "now"())) OR (("e"."event_end" IS NULL) AND ("e"."date" < CURRENT_DATE)))
  ORDER BY COALESCE("e"."event_end", "e"."date") DESC;


ALTER VIEW "public"."past_events" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."upcoming_events" AS
 SELECT "e"."id",
    "e"."event_name",
    "e"."date",
    "e"."organization_id",
    "e"."description",
    "e"."location",
    "e"."created_by",
    "e"."created_at",
    "e"."updated_at",
    "e"."event_start",
    "e"."event_end",
    "o"."name" AS "organization_name",
    "o"."tag" AS "organization_tag"
   FROM ("public"."events" "e"
     JOIN "public"."organizations" "o" ON (("o"."id" = "e"."organization_id")))
  WHERE ((("e"."event_start" IS NOT NULL) AND ("e"."event_start" > "now"())) OR (("e"."event_start" IS NULL) AND ("e"."date" > "now"())))
  ORDER BY COALESCE("e"."event_start", "e"."date");


ALTER VIEW "public"."upcoming_events" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."user_attendance_stats" AS
 SELECT "u"."id" AS "user_id",
    "u"."name" AS "user_name",
    "u"."email" AS "user_email",
    "om"."organization_id",
    "org"."name" AS "organization_name",
    "count"(DISTINCT "e"."id") AS "total_events",
    "count"(DISTINCT "ea"."id") AS "events_attended",
    ("count"(DISTINCT "e"."id") - "count"(DISTINCT "ea"."id")) AS "events_missed",
        CASE
            WHEN ("count"(DISTINCT "e"."id") > 0) THEN "round"(((("count"(DISTINCT "ea"."id"))::numeric / ("count"(DISTINCT "e"."id"))::numeric) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS "attendance_rate"
   FROM (((("public"."users" "u"
     JOIN "public"."organization_members" "om" ON (("u"."id" = "om"."user_id")))
     JOIN "public"."organizations" "org" ON (("om"."organization_id" = "org"."id")))
     LEFT JOIN "public"."events" "e" ON (("e"."organization_id" = "om"."organization_id")))
     LEFT JOIN "public"."event_attendance" "ea" ON ((("ea"."event_id" = "e"."id") AND ("ea"."user_id" = "u"."id"))))
  GROUP BY "u"."id", "u"."name", "u"."email", "om"."organization_id", "org"."name";


ALTER VIEW "public"."user_attendance_stats" OWNER TO "postgres";


COMMENT ON VIEW "public"."user_attendance_stats" IS 'Attendance statistics per user per organization';



