CREATE POLICY "Admins and Attendance Takers can create events" ON "public"."events" FOR INSERT TO "authenticated" WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."organization_members" "om"
  WHERE (("om"."organization_id" = "events"."organization_id") AND ("om"."user_id" = "auth"."uid"()) AND ("om"."role" = ANY (ARRAY['Owner'::"text", 'Admin'::"text", 'Attendance Taker'::"text"]))))));



CREATE POLICY "Authenticated users can create organizations" ON "public"."organizations" FOR INSERT TO "authenticated" WITH CHECK (("owner_user_id" = "auth"."uid"()));



CREATE POLICY "Members can view organization events" ON "public"."events" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."organization_members" "om"
  WHERE (("om"."organization_id" = "events"."organization_id") AND ("om"."user_id" = "auth"."uid"())))));



CREATE POLICY "Owners can delete their organizations" ON "public"."organizations" FOR DELETE TO "authenticated" USING (("owner_user_id" = "auth"."uid"()));



CREATE POLICY "Owners can update their organizations" ON "public"."organizations" FOR UPDATE TO "authenticated" USING (("owner_user_id" = "auth"."uid"())) WITH CHECK (("owner_user_id" = "auth"."uid"()));



CREATE POLICY "Service role can manage all calendar sync" ON "public"."member_calendar_sync" USING ((("auth"."jwt"() ->> 'role'::"text") = 'service_role'::"text"));



CREATE POLICY "Service role can manage all event calendar mappings" ON "public"."event_calendar_mapping" USING ((("auth"."jwt"() ->> 'role'::"text") = 'service_role'::"text"));



CREATE POLICY "Users can delete their own calendar sync" ON "public"."member_calendar_sync" FOR DELETE USING (("membership_id" IN ( SELECT "organization_members"."id"
   FROM "public"."organization_members"
  WHERE ("organization_members"."user_id" = "auth"."uid"()))));



CREATE POLICY "Users can insert their own calendar sync" ON "public"."member_calendar_sync" FOR INSERT WITH CHECK (("membership_id" IN ( SELECT "organization_members"."id"
   FROM "public"."organization_members"
  WHERE ("organization_members"."user_id" = "auth"."uid"()))));



CREATE POLICY "Users can insert their own profile" ON "public"."users" FOR INSERT TO "authenticated" WITH CHECK (("id" = "auth"."uid"()));



CREATE POLICY "Users can update their own calendar sync" ON "public"."member_calendar_sync" FOR UPDATE USING (("membership_id" IN ( SELECT "organization_members"."id"
   FROM "public"."organization_members"
  WHERE ("organization_members"."user_id" = "auth"."uid"()))));



CREATE POLICY "Users can update their own profile" ON "public"."users" FOR UPDATE TO "authenticated" USING (("id" = "auth"."uid"())) WITH CHECK (("id" = "auth"."uid"()));



CREATE POLICY "Users can view all organizations" ON "public"."organizations" FOR SELECT TO "authenticated" USING (true);



CREATE POLICY "Users can view all user profiles" ON "public"."users" FOR SELECT TO "authenticated" USING (true);



CREATE POLICY "Users can view their own calendar sync" ON "public"."member_calendar_sync" FOR SELECT USING (("membership_id" IN ( SELECT "organization_members"."id"
   FROM "public"."organization_members"
  WHERE ("organization_members"."user_id" = "auth"."uid"()))));



